/** Material file-icon theme's React mark — what the app shows next to a .tsx file. */
export function ReactFileIcon({ size = 11, className }: { size?: number; className?: string }) {
  return (
    <svg width={size} height={size} viewBox="0 0 24 24" fill="none" className={className}>
      <circle cx={12} cy={12} r={2.2} fill="#61dafb" />
      <g stroke="#61dafb" strokeWidth={1.2} fill="none">
        <ellipse cx={12} cy={12} rx={9.6} ry={4} />
        <ellipse cx={12} cy={12} rx={9.6} ry={4} transform="rotate(60 12 12)" />
        <ellipse cx={12} cy={12} rx={9.6} ry={4} transform="rotate(120 12 12)" />
      </g>
    </svg>
  );
}

/** The blue "open in editor" chip in the title bar. */
